<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Study;
use App\Domain\Study\ReadModel\StudyContestSubject;use App\Domain\Study\Repository\StudyContestSubjectRepositoryInterface;use App\Infrastructure\Persistence\Doctrine\Catalog\Entity\PositionTaxonomyAssignmentRecord;use App\Infrastructure\Persistence\Doctrine\Taxonomy\Entity\TaxonomySubjectRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineStudyContestSubjectRepository implements StudyContestSubjectRepositoryInterface { public function __construct(private readonly EntityManagerInterface $em){} public function listForPosition(string $positionId):array { $rows=$this->em->createQueryBuilder()->select('taxonomy.id AS id,taxonomy.parentId AS parentId,taxonomy.name AS name,taxonomy.level AS level')->from(PositionTaxonomyAssignmentRecord::class,'assignment')->innerJoin(TaxonomySubjectRecord::class,'taxonomy','WITH','taxonomy.id=assignment.taxonomySubjectId')->where('assignment.positionId=:positionId')->andWhere('taxonomy.active=true')->setParameter('positionId',$positionId)->orderBy('taxonomy.level','ASC')->addOrderBy('taxonomy.name','ASC')->getQuery()->getArrayResult();return array_map(static fn(array $r)=>new StudyContestSubject((string)$r['id'],$r['parentId']===null?null:(string)$r['parentId'],(string)$r['name'],(int)$r['level']),$rows); } }
